class CustomNorm(nn.Module):
    """Adaptive Power Normalization: per-channel learnable power applied after BN.
    y = sign(BN(x)) * |BN(x)|^p where p in [0.3, 0.7] adapts per-channel."""
    def __init__(self, num_features):
        super().__init__()
        self.bn = nn.BatchNorm2d(num_features, track_running_stats=True)
        self.alpha = nn.Parameter(torch.zeros(num_features))
    def forward(self, x):
        x = self.bn(x)
        p = (torch.sigmoid(self.alpha / 4.0) * 0.4 + 0.3).view(1, -1, 1, 1)
        return x.sign() * x.abs().pow(p)
